const NEOCENTRAL_ART = { w: 890, h: 413, door: 0.565, src: 'data:image/webp;base64,' };
if (typeof Image !== "undefined") { NEOCENTRAL_ART.img = new Image(); NEOCENTRAL_ART.img.src = NEOCENTRAL_ART.src; }
NEOCENTRAL_ART.material = function () { if (!this._m) { const tex = new THREE.Texture(this.img); tex.colorSpace = THREE.SRGBColorSpace; tex.anisotropy = 8; const m = new THREE.MeshBasicMaterial({ map: tex });
    const up = () => { tex.needsUpdate = true; m.visible = true; }; if (this.img.complete && this.img.naturalWidth) up(); else { m.visible = false; this.img.addEventListener('load', up); } this._m = m; } return this._m; };
